 ParticleSystem Particles(string n,Transform parent,Color color,int rate,float life,float size,float speed){var g=new GameObject(n);g.transform.SetParent(parent);var p=g.AddComponent<ParticleSystem>();var m=p.main;m.startColor=color;m.startLifetime=life;m.startSize=size;m.startSpeed=speed;m.maxParticles=800;m.simulationSpace=ParticleSystemSimulationSpace.World;var e=p.emission;e.rateOverTime=rate;g.GetComponent<ParticleSystemRenderer>().sharedMaterial=Mat(color);return p;}
