 public void Move(Vector2 axes,Vector2 look,bool run,bool jump,float dt){yaw+=look.x*2.3f;pitch=Mathf.Clamp(pitch-look.y*1.7f,15,65);Vector3 dir=Quaternion.Euler(0,yaw,0)*new Vector3(axes.x,0,axes.y);dir=Vector3.ClampMagnitude(dir,1);if(controller.isGrounded){vertical=-2;if(jump)vertical=7;}vertical-=19*dt;controller.Move((dir*(run?8:4.5f)+Vector3.up*vertical)*dt);Vector3 pos=avatar.position;pos.x=Mathf.Clamp(pos.x,-35,35);pos.z=Mathf.Clamp(pos.z,-32,32);avatar.position=pos;
 if(dir.sqrMagnitude>.01f)body.rotation=Quaternion.Slerp(body.rotation,Quaternion.LookRotation(dir),1-Mathf.Exp(-dt*12));stride+=dt*(run?17:11)*dir.magnitude;float a=Mathf.Sin(stride)*(run?45:28)*dir.magnitude;leftLeg.localRotation=Quaternion.Euler(a,0,0);rightLeg.localRotation=Quaternion.Euler(-a,0,0);leftArm.localRotation=Quaternion.Euler(-a,0,0);rightArm.localRotation=Quaternion.Euler(a,0,0);Follow(dt);}
 public void Follow(float dt){Vector3 target=avatar.position+Vector3.up*1.4f;Vector3 off=Quaternion.Euler(pitch,yaw,0)*Vector3.back*10;RaycastHit hit;if(Physics.SphereCast(target,.25f,off.normalized,out hit,10,Physics.DefaultRaycastLayers,QueryTriggerInteraction.Ignore))off=off.normalized*Mathf.Max(2,hit.distance-.3f);camera.transform.position=Vector3.Lerp(camera.transform.position,target+off,1-Mathf.Exp(-dt*8));camera.transform.LookAt(target);}
 public void Cinematic(float t,bool ending){Vector3 target=ending?new Vector3(0,1,9):new Vector3(-12,1,7);float a=t*.12f;camera.transform.position=target+new Vector3(Mathf.Sin(a)*27,15,Mathf.Cos(a)*27);camera.transform.LookAt(target);}
 public Site Nearest(){Site nearest=null;float d=3.3f;foreach(var s in sites){float n=Vector2.Distance(new Vector2(avatar.position.x,avatar.position.z),new Vector2(s.position.x,s.position.z));if(n<d){d=n;nearest=s;}}return nearest;}
 public void Visuals(JalSimulation s,float clock){float recovery=Mathf.Clamp01((s.prosperity+s.biodiversity)/120);if(s.finished&&!s.won)recovery=0;landMat.color=Color.Lerp(dry,green,recovery);forestMat.color=Color.Lerp(new Color(.45f,.34f,.17f),green,recovery);waterMat.color=Color.Lerp(new Color(.38f,.29f,.18f),blue,s.quality/100);pond.gameObject.SetActive(s.pond>.2f);pond.localScale=new Vector3(2+11*s.pond/100,.025f,1.5f+8*s.pond/100);pond.position=new Vector3(-16,.16f+.23f*s.pond/100,9);
 channel.gameObject.SetActive(s.inlet&&s.Rain>0);runoff.gameObject.SetActive(!s.inlet&&s.Rain>0);river.gameObject.SetActive(s.Rain>0||s.floodRisk>10);river.localScale=new Vector3(1+s.Rain*1.3f,.06f,52);tankWater.gameObject.SetActive(s.tankBuilt&&s.tank>0);tankWater.localScale=new Vector3(3.5f*s.tank/60,.02f,3.5f*s.tank/60);
 for(int i=0;i<flow.Count;i++){flow[i].gameObject.SetActive(s.Rain>0);flow[i].position=new Vector3(s.inlet?-16:-25,s.inlet?.33f:.18f,(s.inlet?23:26)-Mathf.Repeat(clock*3+i*.65f,s.inlet?8:14));}
